import type { ClonePatch, CloneSource, CloneSourceRegion } from './index.js';
import { TiledPixelStore } from '@freetoshop/pixel-storage';
import {
  BrushPoint,
  coverageStoreSample,
  clampIndex,
  documentDabBounds,
  maskCoverage,
  paintMaskStroke as rasterPaintMaskStroke,
  paintStroke as rasterPaintStroke,
  readSelectionRegion,
  selectionCoverage,
  type MaskBrushOptions,
} from './index.js';

export interface CloneStampBrushOptions {
  readonly size: number;
  readonly hardness: number;
  readonly opacity: number;
  readonly aligned: boolean;
}

/**
 * Source-destination offset established at the Alt/Option-click moment.
 * In aligned mode this offset is preserved throughout the gesture.
 */
export interface CloneOffset {
  readonly sourceX: number;
  readonly sourceY: number;
}

/**
 * Computes the source sample coordinate for a destination point.
 *
 * - Aligned mode: `source = destination - offset` where offset is fixed
 *   from the establish-click.
 * - Unaligned mode: `source = origin` (constant source origin).
 */
export function cloneSamplePoint(
  destination: number,
  sourceOrigin: number,
  offset: number,
  aligned: boolean,
): number {
  return aligned ? destination - offset : sourceOrigin;
}

/**
 * Reads source pixels from a TiledPixelStore for a destination dab's source coordinate.
 * Returns the pixels in a small local buffer (never the whole layer).
 */
export function readCloneSourceRegion(
  sourceStore: TiledPixelStore,
  sourceX: number,
  sourceY: number,
  radius: number,
): CloneSourceRegion {
  const bounds = documentDabBounds(sourceX, sourceY, radius, sourceStore.width, sourceStore.height);
  const region = sourceStore.read({
    x: bounds.left,
    y: bounds.top,
    width: bounds.right - bounds.left + 1,
    height: bounds.bottom - bounds.top + 1,
  });
  // Return a cloneable region descriptor (not a live reference).
  return {
    x: bounds.left,
    y: bounds.top,
    width: bounds.right - bounds.left + 1,
    height: bounds.bottom - bounds.top + 1,
    pixels: new Uint8ClampedArray(region),
  };
}

/**
 * Cloned source pixel sampling for a single destination pixel.
 * The source coordinate is in the *source* layer's local space (already transformed).
 */
export function cloneSamplePixel(
  sourceRegion: CloneSourceRegion,
  localSourceX: number,
  localSourceY: number,
  destinationOffset: number,
  destinationPixels: Uint8ClampedArray,
  opacity: number,
): void {
  const sx = clampIndex(localSourceX, sourceRegion.width);
  const sy = clampIndex(localSourceY, sourceRegion.height);
  const sourceOffset = (sy * sourceRegion.width + sx) * 4;
  const srcR = sourceRegion.pixels[sourceOffset] ?? 0;
  const srcG = sourceRegion.pixels[sourceOffset + 1] ?? 0;
  const srcB = sourceRegion.pixels[sourceOffset + 2] ?? 0;
  const srcA = sourceRegion.pixels[sourceOffset + 3] ?? 0;

  // Composite source-over with the source pixel's own alpha.
  const srcAlpha = (srcA / 255) * opacity;
  const dstAlpha = (destinationPixels[destinationOffset + 3] ?? 0) / 255;
  const outAlpha = srcAlpha + dstAlpha * (1 - srcAlpha);
  if (outAlpha === 0) return;
  destinationPixels[destinationOffset] = Math.round((srcR * srcAlpha + (destinationPixels[destinationOffset] ?? 0) * dstAlpha * (1 - srcAlpha)) / outAlpha);
  destinationPixels[destinationOffset + 1] = Math.round((srcG * srcAlpha + (destinationPixels[destinationOffset + 1] ?? 0) * dstAlpha * (1 - srcAlpha)) / outAlpha);
  destinationPixels[destinationOffset + 2] = Math.round((srcB * srcAlpha + (destinationPixels[destinationOffset + 2] ?? 0) * dstAlpha * (1 - srcAlpha)) / outAlpha);
  destinationPixels[destinationOffset + 3] = Math.round(outAlpha * 255);
}

export interface CloneStampStrokeOptions {
  readonly sourceStore: TiledPixelStore;
  readonly sourceLayerWorldTransform: {
    a: number;
    b: number;
    c: number;
    d: number;
    e: number;
    f: number;
  };
  readonly sourceInverseTransform: {
    a: number;
    b: number;
    c: number;
    d: number;
    e: number;
    f: number;
  };
  readonly sourceOriginX: number;
  readonly sourceOriginY: number;
  readonly aligned: boolean;
  readonly selection?: import('@freetoshop/core-document').SelectionMask | null;
  readonly destinationLayerWidth: number;
  readonly destinationLayerHeight: number;
  readonly destinationLayerTransform: {
    a: number;
    b: number;
    c: number;
    d: number;
    e: number;
    f: number;
  };
  readonly destinationInverseTransform: {
    a: number;
    b: number;
    c: number;
    d: number;
    e: number;
    f: number;
  };
  readonly brushOptions: CloneStampBrushOptions;
}

/**
 * Computes the source offset established at the Alt/Option-click.
 * The offset is in *destination document space* and is preserved in aligned mode.
 */
export function establishCloneOffset(
  establishDestination: BrushPoint,
  sourceDocumentPoint: { x: number; y: number },
): CloneOffset {
  return {
    sourceX: sourceDocumentPoint.x - establishDestination.x,
    sourceY: sourceDocumentPoint.y - establishDestination.y,
  };
}

/**
 * For a destination point (document space), compute the source point (source layer local space)
 * that should be sampled.
 */
export function destinationToSourceLocal(
  destinationPoint: BrushPoint,
  sourceOriginX: number,
  sourceOriginY: number,
  offset: CloneOffset,
  aligned: boolean,
  sourceLayerWorldTransform: {
    a: number;
    b: number;
    c: number;
    d: number;
    e: number;
    f: number;
  },
  sourceInverseTransform: {
    a: number;
    b: number;
    c: number;
    d: number;
    e: number;
    f: number;
  },
): { x: number; y: number } {
  // First, compute the source document-space point.
  let sourceDocX: number;
  let sourceDocY: number;
  if (aligned) {
    // Aligned: source follows destination with fixed offset.
    sourceDocX = destinationPoint.x + offset.sourceX;
    sourceDocY = destinationPoint.y + offset.sourceY;
  } else {
    // Unaligned: source is always at origin.
    sourceDocX = sourceOriginX;
    sourceDocY = sourceOriginY;
  }

  // Transform source document point into source layer local space.
  const localX = sourceInverseTransform.a * sourceDocX + sourceInverseTransform.c * sourceDocY + sourceInverseTransform.e;
  const localY = sourceInverseTransform.b * sourceDocX + sourceInverseTransform.d * sourceDocY + sourceInverseTransform.f;
  return { x: localX, y: localY };
}

/**
 * Paint a clone stamp stroke into a destination raster buffer (in destination layer local space).
 * Returns a pixel patch covering the painted region.
 *
 * This is the core algorithm. It is deliberately separate from UI concerns and operates on
 * explicit source/destination stores and transforms.
 */
export function cloneStampStroke(
  options: CloneStampStrokeOptions,
): ClonePatch {
  const {
    sourceStore,
    sourceInverseTransform,
    sourceOriginX,
    sourceOriginY,
    aligned,
    selection,
    destinationLayerWidth,
    destinationLayerHeight,
    destinationInverseTransform,
    brushOptions,
  } = options;

  const { size, hardness, opacity, aligned: _aligned } = brushOptions;
  if (size <= 0 || opacity <= 0) return { x: 0, y: 0, width: 0, height: 0, pixels: new Uint8ClampedArray() };
  if (opacity > 1) throw new Error('Clone stamp opacity must be in [0, 1]');

  const radius = size / 2;

  // Build dab points (interpolated).
  const points: Array<{ x: number; y: number; pressure: number }> = [];
  if (options.points.length === 0) return { x: 0, y: 0, width: 0, height: 0, pixels: new Uint8ClampedArray() };

  const first = options.points[0];
  points.push({ x: first.x, y: first.y, pressure: first.pressure ?? 1 });
  for (let i = 1; i < options.points.length; i++) {
    const prev = options.points[i - 1];
    const curr = options.points[i];
    const dist = Math.hypot(curr.x - prev.x, curr.y - prev.y);
    const steps = Math.max(1, Math.ceil(dist / Math.max(0.25, radius * 0.5)));
    for (let s = 1; s <= steps; s++) {
      const t = s / steps;
      points.push({
        x: prev.x + (curr.x - prev.x) * t,
        y: prev.y + (curr.y - prev.y) * t,
        pressure: (prev.pressure ?? 1) + ((curr.pressure ?? 1) - (prev.pressure ?? 1)) * t,
      });
    }
  }

  // Compute destination working region bounds (in destination local space).
  let minX = destinationLayerWidth;
  let minY = destinationLayerHeight;
  let maxX = -1;
  let maxY = -1;
  const destPoints: Array<{ x: number; y: number }> = [];
  for (const p of points) {
    const localX = destinationInverseTransform.a * p.x + destinationInverseTransform.c * p.y + destinationInverseTransform.e;
    const localY = destinationInverseTransform.b * p.x + destinationInverseTransform.d * p.y + destinationInverseTransform.f;
    const halfExtentX = radius * Math.hypot(destinationInverseTransform.a, destinationInverseTransform.c);
    const halfExtentY = radius * Math.hypot(destinationInverseTransform.b, destinationInverseTransform.d);
    const left = Math.max(0, Math.floor(localX - halfExtentX));
    const top = Math.max(0, Math.floor(localY - halfExtentY));
    const right = Math.min(destinationLayerWidth - 1, Math.ceil(localX + halfExtentX));
    const bottom = Math.min(destinationLayerHeight - 1, Math.ceil(localY + halfExtentY));
    minX = Math.min(minX, left);
    minY = Math.min(minY, top);
    maxX = Math.max(maxX, right);
    maxY = Math.max(maxY, bottom);
    destPoints.push({ x: localX, y: localY });
  }

  if (minX > maxX || minY > maxY) return { x: 0, y: 0, width: 0, height: 0, pixels: new Uint8ClampedArray() };

  const patchWidth = maxX - minX + 1;
  const patchHeight = maxY - minY + 1;
  const patchPixels = new Uint8ClampedArray(patchWidth * patchHeight * 4);

  // Read destination region (for compositing and bounds).
  // We need destination pixels to composite source-over.
  // For a new layer (transparent), this is all zeros. But we read existing to respect current content.
  // The destination store is abstracted away; we take the destination pixels as a parameter.
  // However, the contract is that we write INTO the destination. The caller provides the region.
  // For this algorithm, we read from the destination's store (passed via options or closure).
  // To keep the function pure, we'll read the destination region and write back.

  // Read existing destination pixels for the working region.
  const existing = options.destinationRegionPixels;
  // Copy into working buffer.
  for (let i = 0; i < existing.length; i++) {
    patchPixels[i] = existing[i];
  }

  // Selection coverage buffer for the working region.
  let selectionBuffer: Uint8ClampedArray | null = null;
  let selectionRegionBounds: { left: number; top: number; right: number; bottom: number } | null = null;
  if (selection != null) {
    const selBounds = documentDabBounds(points[0].x, points[0].y, radius, selection.width, selection.height);
    for (const p of points) {
      const db = documentDabBounds(p.x, p.y, radius, selection.width, selection.height);
      selBounds.left = Math.min(selBounds.left, db.left);
      selBounds.top = Math.min(selBounds.top, db.top);
      selBounds.right = Math.max(selBounds.right, db.right);
      selBounds.bottom = Math.max(selBounds.bottom, db.bottom);
    }
    selectionRegionBounds = selBounds;
    const selWidth = selBounds.right - selBounds.left + 1;
    const selHeight = selBounds.bottom - selBounds.top + 1;
    selectionBuffer = selection.coverageStore.read({
      x: selBounds.left,
      y: selBounds.top,
      width: selWidth,
      height: selHeight,
    }).slice();
  }

  // Paint each dab.
  for (let pi = 0; pi < points.length; pi++) {
    const p = points[pi];
    const destLocalX = destinationInverseTransform.a * p.x + destinationInverseTransform.c * p.y + destinationInverseTransform.e;
    const destLocalY = destinationInverseTransform.b * p.x + destinationInverseTransform.d * p.y + destinationInverseTransform.f;

    const sourceLocal = destinationToSourceLocal(
      p,
      sourceOriginX,
      sourceOriginY,
      { sourceX: sourceOriginX - p.x, sourceY: sourceOriginY - p.y },
      aligned,
      { a: 1, b: 0, c: 0, d: 1, e: 0, f: 0 },
      sourceInverseTransform,
    );

    // Source region for this dab.
    const srcHalfExtentX = radius * Math.hypot(sourceInverseTransform.a, sourceInverseTransform.c);
    const srcHalfExtentY = radius * Math.hypot(sourceInverseTransform.b, sourceInverseTransform.d);
    const srcBounds = {
      left: Math.max(0, Math.floor(sourceLocal.x - srcHalfExtentX)),
      top: Math.max(0, Math.floor(sourceLocal.y - srcHalfExtentY)),
      right: Math.min(sourceStore.width - 1, Math.ceil(sourceLocal.x + srcHalfExtentX)),
      bottom: Math.min(sourceStore.height - 1, Math.ceil(sourceLocal.y + srcHalfExtentY)),
    };
    if (srcBounds.left > srcBounds.right || srcBounds.top > srcBounds.bottom) continue;

    const srcRegion = sourceStore.read({
      x: srcBounds.left,
      y: srcBounds.top,
      width: srcBounds.right - srcBounds.left + 1,
      height: srcBounds.bottom - srcBounds.top + 1,
    });

    // For each pixel in destination working region, compute coverage.
    const destDabLeft = Math.max(minX, Math.floor(destLocalX - radius));
    const destDabTop = Math.max(minY, Math.floor(destLocalY - radius));
    const destDabRight = Math.min(maxX, Math.ceil(destLocalX + radius));
    const destDabBottom = Math.min(maxY, Math.ceil(destLocalY + radius));

    for (let y = destDabTop; y <= destDabBottom; y++) {
      for (let x = destDabLeft; x <= destDabRight; x++) {
        const dx = x - destLocalX;
        const dy = y - destLocalY;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist > radius) continue;

        const falloff = dist <= radius * hardness ? 1 : 1 - (dist - radius * hardness) / (radius - radius * hardness);
        const strength = falloff * opacity * p.pressure;

        // Selection coverage at this destination document point.
        const docX = p.x;
        const docY = p.y;
        const selX = Math.floor(docX);
        const selY = Math.floor(docY);
        let selected = 1;
        if (selection != null && selX >= 0 && selY >= 0 && selX < selection.width && selY < selection.height) {
          const selLocalX = selX - selectionRegionBounds!.left;
          const selLocalY = selY - selectionRegionBounds!.top;
          if (selLocalX >= 0 && selLocalY >= 0 && selLocalX < selectionBuffer!.length / selectionBuffer!.length /* always true */) {
            // coverageStore.read returns Uint8ClampedArray; index by selLocalY * selWidth + selLocalX.
            const idx = selLocalY * (selectionRegionBounds!.right - selectionRegionBounds!.left + 1) + selLocalX;
            if (idx >= 0 && idx < selectionBuffer!.length) {
              selected = selectionBuffer![idx] / 255;
            }
          }
        }
        const effectiveStrength = strength * selected;
        if (effectiveStrength <= 0) continue;

        // Sample source pixel at (x, y) in source local space.
        const srcX = sourceLocal.x + (x - destLocalX);
        const srcY = sourceLocal.y + (y - destLocalY);
        const srcLocalX = srcX - srcBounds.left;
        const srcLocalY = srcY - srcBounds.top;
        const srcClampedX = clampIndex(Math.round(srcLocalX), srcRegion.width);
        const srcClampedY = clampIndex(Math.round(srcLocalY), srcRegion.height);
        const srcOffset = (srcClampedY * srcRegion.width + srcClampedX) * 4;
        const srcR = srcRegion[srcOffset] ?? 0;
        const srcG = srcRegion[srcOffset + 1] ?? 0;
        const srcB = srcRegion[srcOffset + 2] ?? 0;
        const srcA = srcRegion[srcOffset + 3] ?? 0;

        // Composite onto destination working buffer.
        const dstOffset = ((y - minY) * patchWidth + (x - minX)) * 4;
        const dstR = patchPixels[dstOffset] ?? 0;
        const dstG = patchPixels[dstOffset + 1] ?? 0;
        const dstB = patchPixels[dstOffset + 2] ?? 0;
        const dstA = patchPixels[dstOffset + 3] ?? 0;

        const srcAlpha = (srcA / 255) * effectiveStrength;
        const dstAlpha = dstA / 255;
        const outAlpha = srcAlpha + dstAlpha * (1 - srcAlpha);
        if (outAlpha === 0) continue;
        patchPixels[dstOffset] = Math.round((srcR * srcAlpha + dstR * dstAlpha * (1 - srcAlpha)) / outAlpha);
        patchPixels[dstOffset + 1] = Math.round((srcG * srcAlpha + dstG * dstAlpha * (1 - srcAlpha)) / outAlpha);
        patchPixels[dstOffset + 2] = Math.round((srcB * srcAlpha + dstB * dstAlpha * (1 - srcAlpha)) / outAlpha);
        patchPixels[dstOffset + 3] = Math.round(outAlpha * 255);
      }
    }
  }

  return { x: minX, y: minY, width: patchWidth, height: patchHeight, pixels: patchPixels };
}

import type { ClonePatch, CloneSource, CloneSourceRegion } from './index.js';
import { TiledPixelStore } from '@freetoshop/pixel-storage';
import {
  BrushPoint,
  coverageStoreSample,
  clampIndex,
  documentDabBounds,
  maskCoverage,
  paintMaskStroke as rasterPaintMaskStroke,
  paintStroke as rasterPaintStroke,
  readSelectionRegion,
  selectionCoverage,
  type MaskBrushOptions,
} from './index.js';

export interface CloneStampBrushOptions {
  readonly size: number;
  readonly hardness: number;
  readonly opacity: number;
  readonly aligned: boolean;
}

/**
 * Source-destination offset established at the Alt/Option-click moment.
 * In aligned mode this offset is preserved throughout the gesture.
 */
export interface CloneOffset {
  readonly sourceX: number;
  readonly sourceY: number;
}

/**
 * Computes the source sample coordinate for a destination point.
 *
 * - Aligned mode: `source = destination - offset` where offset is fixed
 *   from the establish-click.
 * - Unaligned mode: `source = origin` (constant source origin).
 */
export function cloneSamplePoint(
  destination: number,
  sourceOrigin: number,
  offset: number,
  aligned: boolean,
): number {
  return aligned ? destination - offset : sourceOrigin;
}

/**
 * Reads source pixels from a TiledPixelStore for a destination dab's source coordinate.
 * Returns the pixels in a small local buffer (never the whole layer).
 */
export function readCloneSourceRegion(
  sourceStore: TiledPixelStore,
  sourceX: number,
  sourceY: number,
  radius: number,
): CloneSourceRegion {
  const bounds = documentDabBounds(sourceX, sourceY, radius, sourceStore.width, sourceStore.height);
  const region = sourceStore.read({
    x: bounds.left,
    y: bounds.top,
    width: bounds.right - bounds.left + 1,
    height: bounds.bottom - bounds.top + 1,
  });
  // Return a cloneable region descriptor (not a live reference).
  return {
    x: bounds.left,
    y: bounds.top,
    width: bounds.right - bounds.left + 1,
    height: bounds.bottom - bounds.top + 1,
    pixels: new Uint8ClampedArray(region),
  };
}

/**
 * Cloned source pixel sampling for a single destination pixel.
 * The source coordinate is in the *source* layer's local space (already transformed).
 */
export function cloneSamplePixel(
  sourceRegion: CloneSourceRegion,
  localSourceX: number,
  localSourceY: number,
  destinationOffset: number,
  destinationPixels: Uint8ClampedArray,
  opacity: number,
): void {
  const sx = clampIndex(localSourceX, sourceRegion.width);
  const sy = clampIndex(localSourceY, sourceRegion.height);
  const sourceOffset = (sy * sourceRegion.width + sx) * 4;
  const srcR = sourceRegion.pixels[sourceOffset] ?? 0;
  const srcG = sourceRegion.pixels[sourceOffset + 1] ?? 0;
  const srcB = sourceRegion.pixels[sourceOffset + 2] ?? 0;
  const srcA = sourceRegion.pixels[sourceOffset + 3] ?? 0;

  // Composite source-over with the source pixel's own alpha.
  const srcAlpha = (srcA / 255) * opacity;
  const dstAlpha = (destinationPixels[destinationOffset + 3] ?? 0) / 255;
  const outAlpha = srcAlpha + dstAlpha * (1 - srcAlpha);
  if (outAlpha === 0) return;
  destinationPixels[destinationOffset] = Math.round((srcR * srcAlpha + (destinationPixels[destinationOffset] ?? 0) * dstAlpha * (1 - srcAlpha)) / outAlpha);
  destinationPixels[destinationOffset + 1] = Math.round((srcG * srcAlpha + (destinationPixels[destinationOffset + 1] ?? 0) * dstAlpha * (1 - srcAlpha)) / outAlpha);
  destinationPixels[destinationOffset + 2] = Math.round((srcB * srcAlpha + (destinationPixels[destinationOffset + 2] ?? 0) * dstAlpha * (1 - srcAlpha)) / outAlpha);
  destinationPixels[destinationOffset + 3] = Math.round(outAlpha * 255);
}

export interface CloneStampStrokeOptions {
  readonly sourceStore: TiledPixelStore;
  readonly sourceLayerWorldTransform: {
    a: number;
    b: number;
    c: number;
    d: number;
    e: number;
    f: number;
  };
  readonly sourceInverseTransform: {
    a: number;
    b: number;
    c: number;
    d: number;
    e: number;
    f: number;
  };
  readonly sourceOriginX: number;
  readonly sourceOriginY: number;
  readonly aligned: boolean;
  readonly selection?: import('@freetoshop/core-document').SelectionMask | null;
  readonly destinationLayerWidth: number;
  readonly destinationLayerHeight: number;
  readonly destinationLayerTransform: {
    a: number;
    b: number;
    c: number;
    d: number;
    e: number;
    f: number;
  };
  readonly destinationInverseTransform: {
    a: number;
    b: number;
    c: number;
    d: number;
    e: number;
    f: number;
  };
  readonly brushOptions: CloneStampBrushOptions;
}

/**
 * Computes the source offset established at the Alt/Option-click.
 * The offset is in *destination document space* and is preserved in aligned mode.
 */
export function establishCloneOffset(
  establishDestination: BrushPoint,
  sourceDocumentPoint: { x: number; y: number },
): CloneOffset {
  return {
    sourceX: sourceDocumentPoint.x - establishDestination.x,
    sourceY: sourceDocumentPoint.y - establishDestination.y,
  };
}

/**
 * For a destination point (document space), compute the source point (source layer local space)
 * that should be sampled.
 */
export function destinationToSourceLocal(
  destinationPoint: BrushPoint,
  sourceOriginX: number,
  sourceOriginY: number,
  offset: CloneOffset,
  aligned: boolean,
  sourceLayerWorldTransform: {
    a: number;
    b: number;
    c: number;
    d: number;
    e: number;
    f: number;
  },
  sourceInverseTransform: {
    a: number;
    b: number;
    c: number;
    d: number;
    e: number;
    f: number;
  },
): { x: number; y: number } {
  // First, compute the source document-space point.
  let sourceDocX: number;
  let sourceDocY: number;
  if (aligned) {
    // Aligned: source follows destination with fixed offset.
    sourceDocX = destinationPoint.x + offset.sourceX;
    sourceDocY = destinationPoint.y + offset.sourceY;
  } else {
    // Unaligned: source is always at origin.
    sourceDocX = sourceOriginX;
    sourceDocY = sourceOriginY;
  }

  // Transform source document point into source layer local space.
  const localX = sourceInverseTransform.a * sourceDocX + sourceInverseTransform.c * sourceDocY + sourceInverseTransform.e;
  const localY = sourceInverseTransform.b * sourceDocX + sourceInverseTransform.d * sourceDocY + sourceInverseTransform.f;
  return { x: localX, y: localY };
}

/**
 * Paint a clone stamp stroke into a destination raster buffer (in destination layer local space).
 * Returns a pixel patch covering the painted region.
 *
 * This is the core algorithm. It is deliberately separate from UI concerns and operates on
 * explicit source/destination stores and transforms.
 */
export function cloneStampStroke(
  options: CloneStampStrokeOptions,
): ClonePatch {
  const {
    sourceStore,
    sourceInverseTransform,
    sourceOriginX,
    sourceOriginY,
    aligned,
    selection,
    destinationLayerWidth,
    destinationLayerHeight,
    destinationInverseTransform,
    brushOptions,
  } = options;

  const { size, hardness, opacity, aligned: _aligned } = brushOptions;
  if (size <= 0 || opacity <= 0) return { x: 0, y: 0, width: 0, height: 0, pixels: new Uint8ClampedArray() };
  if (opacity > 1) throw new Error('Clone stamp opacity must be in [0, 1]');

  const radius = size / 2;

  // Build dab points (interpolated).
  const points: Array<{ x: number; y: number; pressure: number }> = [];
  if (options.points.length === 0) return { x: 0, y: 0, width: 0, height: 0, pixels: new Uint8ClampedArray() };

  const first = options.points[0];
  points.push({ x: first.x, y: first.y, pressure: first.pressure ?? 1 });
  for (let i = 1; i < options.points.length; i++) {
    const prev = options.points[i - 1];
    const curr = options.points[i];
    const dist = Math.hypot(curr.x - prev.x, curr.y - prev.y);
    const steps = Math.max(1, Math.ceil(dist / Math.max(0.25, radius * 0.5)));
    for (let s = 1; s <= steps; s++) {
      const t = s / steps;
      points.push({
        x: prev.x + (curr.x - prev.x) * t,
        y: prev.y + (curr.y - prev.y) * t,
        pressure: (prev.pressure ?? 1) + ((curr.pressure ?? 1) - (prev.pressure ?? 1)) * t,
      });
    }
  }

  // Compute destination working region bounds (in destination local space).
  let minX = destinationLayerWidth;
  let minY = destinationLayerHeight;
  let maxX = -1;
  let maxY = -1;
  const destPoints: Array<{ x: number; y: number }> = [];
  for (const p of points) {
    const localX = destinationInverseTransform.a * p.x + destinationInverseTransform.c * p.y + destinationInverseTransform.e;
    const localY = destinationInverseTransform.b * p.x + destinationInverseTransform.d * p.y + destinationInverseTransform.f;
    const halfExtentX = radius * Math.hypot(destinationInverseTransform.a, destinationInverseTransform.c);
    const halfExtentY = radius * Math.hypot(destinationInverseTransform.b, destinationInverseTransform.d);
    const left = Math.max(0, Math.floor(localX - halfExtentX));
    const top = Math.max(0, Math.floor(localY - halfExtentY));
    const right = Math.min(destinationLayerWidth - 1, Math.ceil(localX + halfExtentX));
    const bottom = Math.min(destinationLayerHeight - 1, Math.ceil(localY + halfExtentY));
    minX = Math.min(minX, left);
    minY = Math.min(minY, top);
    maxX = Math.max(maxX, right);
    maxY = Math.max(maxY, bottom);
    destPoints.push({ x: localX, y: localY });
  }

  if (minX > maxX || minY > maxY) return { x: 0, y: 0, width: 0, height: 0, pixels: new Uint8ClampedArray() };

  const patchWidth = maxX - minX + 1;
  const patchHeight = maxY - minY + 1;
  const patchPixels = new Uint8ClampedArray(patchWidth * patchHeight * 4);

  // Read destination region (for compositing and bounds).
  // We need destination pixels to composite source-over.
  // For a new layer (transparent), this is all zeros. But we read existing to respect current content.
  // The destination store is abstracted away; we take the destination pixels as a parameter.
  // However, the contract is that we write INTO the destination. The caller provides the region.
  // For this algorithm, we read from the destination's store (passed via options or closure).
  // To keep the function pure, we'll read the destination region and write back.

  // Read existing destination pixels for the working region.
  const existing = options.destinationRegionPixels;
  // Copy into working buffer.
  for (let i = 0; i < existing.length; i++) {
    patchPixels[i] = existing[i];
  }

  // Selection coverage buffer for the working region.
  let selectionBuffer: Uint8ClampedArray | null = null;
  let selectionRegionBounds: { left: number; top: number; right: number; bottom: number } | null = null;
  if (selection != null) {
    const selBounds = documentDabBounds(points[0].x, points[0].y, radius, selection.width, selection.height);
    for (const p of points) {
      const db = documentDabBounds(p.x, p.y, radius, selection.width, selection.height);
      selBounds.left = Math.min(selBounds.left, db.left);
      selBounds.top = Math.min(selBounds.top, db.top);
      selBounds.right = Math.max(selBounds.right, db.right);
      selBounds.bottom = Math.max(selBounds.bottom, db.bottom);
    }
    selectionRegionBounds = selBounds;
    const selWidth = selBounds.right - selBounds.left + 1;
    const selHeight = selBounds.bottom - selBounds.top + 1;
    selectionBuffer = selection.coverageStore.read({
      x: selBounds.left,
      y: selBounds.top,
      width: selWidth,
      height: selHeight,
    }).slice();
  }

  // Paint each dab.
  for (let pi = 0; pi < points.length; pi++) {
    const p = points[pi];
    const destLocalX = destinationInverseTransform.a * p.x + destinationInverseTransform.c * p.y + destinationInverseTransform.e;
    const destLocalY = destinationInverseTransform.b * p.x + destinationInverseTransform.d * p.y + destinationInverseTransform.f;

    const sourceLocal = destinationToSourceLocal(
      p,
      sourceOriginX,
      sourceOriginY,
      { sourceX: sourceOriginX - p.x, sourceY: sourceOriginY - p.y },
      aligned,
      { a: 1, b: 0, c: 0, d: 1, e: 0, f: 0 },
      sourceInverseTransform,
    );

    // Source region for this dab.
    const srcHalfExtentX = radius * Math.hypot(sourceInverseTransform.a, sourceInverseTransform.c);
    const srcHalfExtentY = radius * Math.hypot(sourceInverseTransform.b, sourceInverseTransform.d);
    const srcBounds = {
      left: Math.max(0, Math.floor(sourceLocal.x - srcHalfExtentX)),
      top: Math.max(0, Math.floor(sourceLocal.y - srcHalfExtentY)),
      right: Math.min(sourceStore.width - 1, Math.ceil(sourceLocal.x + srcHalfExtentX)),
      bottom: Math.min(sourceStore.height - 1, Math.ceil(sourceLocal.y + srcHalfExtentY)),
    };
    if (srcBounds.left > srcBounds.right || srcBounds.top > srcBounds.bottom) continue;

    const srcRegion = sourceStore.read({
      x: srcBounds.left,
      y: srcBounds.top,
      width: srcBounds.right - srcBounds.left + 1,
      height: srcBounds.bottom - srcBounds.top + 1,
    });

    // For each pixel in destination working region, compute coverage.
    const destDabLeft = Math.max(minX, Math.floor(destLocalX - radius));
    const destDabTop = Math.max(minY, Math.floor(destLocalY - radius));
    const destDabRight = Math.min(maxX, Math.ceil(destLocalX + radius));
    const destDabBottom = Math.min(maxY, Math.ceil(destLocalY + radius));

    for (let y = destDabTop; y <= destDabBottom; y++) {
      for (let x = destDabLeft; x <= destDabRight; x++) {
        const dx = x - destLocalX;
        const dy = y - destLocalY;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist > radius) continue;

        const falloff = dist <= radius * hardness ? 1 : 1 - (dist - radius * hardness) / (radius - radius * hardness);
        const strength = falloff * opacity * p.pressure;

        // Selection coverage at this destination document point.
        const docX = p.x;
        const docY = p.y;
        const selX = Math.floor(docX);
        const selY = Math.floor(docY);
        let selected = 1;
        if (selection != null && selX >= 0 && selY >= 0 && selX < selection.width && selY < selection.height) {
          const selLocalX = selX - selectionRegionBounds!.left;
          const selLocalY = selY - selectionRegionBounds!.top;
          if (selLocalX >= 0 && selLocalY >= 0 && selLocalX < selectionBuffer!.length / selectionBuffer!.length /* always true */) {
            // coverageStore.read returns Uint8ClampedArray; index by selLocalY * selWidth + selLocalX.
            const idx = selLocalY * (selectionRegionBounds!.right - selectionRegionBounds!.left + 1) + selLocalX;
            if (idx >= 0 && idx < selectionBuffer!.length) {
              selected = selectionBuffer![idx] / 255;
            }
          }
        }
        const effectiveStrength = strength * selected;
        if (effectiveStrength <= 0) continue;

        // Sample source pixel at (x, y) in source local space.
        const srcX = sourceLocal.x + (x - destLocalX);
        const srcY = sourceLocal.y + (y - destLocalY);
        const srcLocalX = srcX - srcBounds.left;
        const srcLocalY = srcY - srcBounds.top;
        const srcClampedX = clampIndex(Math.round(srcLocalX), srcRegion.width);
        const srcClampedY = clampIndex(Math.round(srcLocalY), srcRegion.height);
        const srcOffset = (srcClampedY * srcRegion.width + srcClampedX) * 4;
        const srcR = srcRegion[srcOffset] ?? 0;
        const srcG = srcRegion[srcOffset + 1] ?? 0;
        const srcB = srcRegion[srcOffset + 2] ?? 0;
        const srcA = srcRegion[srcOffset + 3] ?? 0;

        // Composite onto destination working buffer.
        const dstOffset = ((y - minY) * patchWidth + (x - minX)) * 4;
        const dstR = patchPixels[dstOffset] ?? 0;
        const dstG = patchPixels[dstOffset + 1] ?? 0;
        const dstB = patchPixels[dstOffset + 2] ?? 0;
        const dstA = patchPixels[dstOffset + 3] ?? 0;

        const srcAlpha = (srcA / 255) * effectiveStrength;
        const dstAlpha = dstA / 255;
        const outAlpha = srcAlpha + dstAlpha * (1 - srcAlpha);
        if (outAlpha === 0) continue;
        patchPixels[dstOffset] = Math.round((srcR * srcAlpha + dstR * dstAlpha * (1 - srcAlpha)) / outAlpha);
        patchPixels[dstOffset + 1] = Math.round((srcG * srcAlpha + dstG * dstAlpha * (1 - srcAlpha)) / outAlpha);
        patchPixels[dstOffset + 2] = Math.round((srcB * srcAlpha + dstB * dstAlpha * (1 - srcAlpha)) / outAlpha);
        patchPixels[dstOffset + 3] = Math.round(outAlpha * 255);
      }
    }
  }

  return { x: minX, y: minY, width: patchWidth, height: patchHeight, pixels: patchPixels };
}

