    const halfExtentX = radius * Math.hypot(destinationInverseTransform.a, destinationInverseTransform.c);
    const halfExtentY = radius * Math.hypot(destinationInverseTransform.b, destinationInverseTransform.d);
    const left = Math.max(0, Math.floor(localX - halfExtentX));
    const top = Math.max(0, Math.floor(localY - halfExtentY));
    const right = Math.min(destinationLayerWidth - 1, Math.ceil(localX + halfExtentX));
    const bottom = Math.min(destinationLayerHeight - 1, Math.ceil(localY + halfExtentY));
    minX = Math.min(minX, left);
    minY = Math.min(minY, top);
    maxX = Math.max(maxX, right);
    maxY = Math.max(maxY, bottom);
    destPoints.push({ x: localX, y: localY });
  }

  if (minX > maxX || minY > maxY) return { x: 0, y: 0, width: 0, height: 0, pixels: new Uint8ClampedArray() };

