  // For this algorithm, we read from the destination's store (passed via options or closure).
  // To keep the function pure, we'll read the destination region and write back.

  // Read existing destination pixels for the working region.
  const existing = options.destinationRegionPixels;
  // Copy into working buffer.
  for (let i = 0; i < existing.length; i++) {
    patchPixels[i] = existing[i];
  }

  // Selection coverage buffer for the working region.
  let selectionBuffer: Uint8ClampedArray | null = null;
  let selectionRegionBounds: { left: number; top: number; right: number; bottom: number } | null = null;
  if (selection != null) {
    const selBounds = documentDabBounds(points[0].x, points[0].y, radius, selection.width, selection.height);
    for (const p of points) {
      const db = documentDabBounds(p.x, p.y, radius, selection.width, selection.height);
      selBounds.left = Math.min(selBounds.left, db.left);
      selBounds.top = Math.min(selBounds.top, db.top);
      selBounds.right = Math.max(selBounds.right, db.right);
      selBounds.bottom = Math.max(selBounds.bottom, db.bottom);
    }
    selectionRegionBounds = selBounds;
    const selWidth = selBounds.right - selBounds.left + 1;
    const selHeight = selBounds.bottom - selBounds.top + 1;
    selectionBuffer = selection.coverageStore.read({
      x: selBounds.left,
      y: selBounds.top,
      width: selWidth,
      height: selHeight,
    }).slice();
  }

