  for (let pi = 0; pi < points.length; pi++) {
    const p = points[pi];
    const destLocalX = destinationInverseTransform.a * p.x + destinationInverseTransform.c * p.y + destinationInverseTransform.e;
    const destLocalY = destinationInverseTransform.b * p.x + destinationInverseTransform.d * p.y + destinationInverseTransform.f;

    const sourceLocal = destinationToSourceLocal(
      p,
      sourceOriginX,
      sourceOriginY,
      { sourceX: sourceOriginX - p.x, sourceY: sourceOriginY - p.y },
      aligned,
      { a: 1, b: 0, c: 0, d: 1, e: 0, f: 0 },
      sourceInverseTransform,
    );

    // Source region for this dab.
    const srcHalfExtentX = radius * Math.hypot(sourceInverseTransform.a, sourceInverseTransform.c);
    const srcHalfExtentY = radius * Math.hypot(sourceInverseTransform.b, sourceInverseTransform.d);
    const srcBounds = {
      left: Math.max(0, Math.floor(sourceLocal.x - srcHalfExtentX)),
      top: Math.max(0, Math.floor(sourceLocal.y - srcHalfExtentY)),
      right: Math.min(sourceStore.width - 1, Math.ceil(sourceLocal.x + srcHalfExtentX)),
      bottom: Math.min(sourceStore.height - 1, Math.ceil(sourceLocal.y + srcHalfExtentY)),
    };
