    const srcRegion = sourceStore.read({
      x: srcBounds.left,
      y: srcBounds.top,
      width: srcBounds.right - srcBounds.left + 1,
      height: srcBounds.bottom - srcBounds.top + 1,
    });

    // For each pixel in destination working region, compute coverage.
    const destDabLeft = Math.max(minX, Math.floor(destLocalX - radius));
    const destDabTop = Math.max(minY, Math.floor(destLocalY - radius));
    const destDabRight = Math.min(maxX, Math.ceil(destLocalX + radius));
    const destDabBottom = Math.min(maxY, Math.ceil(destLocalY + radius));

    for (let y = destDabTop; y <= destDabBottom; y++) {
      for (let x = destDabLeft; x <= destDabRight; x++) {
        const dx = x - destLocalX;
        const dy = y - destLocalY;
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist > radius) continue;

        const falloff = dist <= radius * hardness ? 1 : 1 - (dist - radius * hardness) / (radius - radius * hardness);
        const strength = falloff * opacity * p.pressure;

        // Selection coverage at this destination document point.
        const docX = p.x;
        const docY = p.y;
        const selX = Math.floor(docX);
        const selY = Math.floor(docY);
        let selected = 1;
        if (selection != null && selX >= 0 && selY >= 0 && selX < selection.width && selY < selection.height) {
          const selLocalX = selX - selectionRegionBounds!.left;
          const selLocalY = selY - selectionRegionBounds!.top;
          if (selLocalX >= 0 && selLocalY >= 0 && selLocalX < selectionBuffer!.length / selectionBuffer!.length /* always true */) {
            // coverageStore.read returns Uint8ClampedArray; index by selLocalY * selWidth + selLocalX.
            const idx = selLocalY * (selectionRegionBounds!.right - selectionRegionBounds!.left + 1) + selLocalX;
            if (idx >= 0 && idx < selectionBuffer!.length) {
              selected = selectionBuffer![idx] / 255;
            }
          }
        }
        const effectiveStrength = strength * selected;
        if (effectiveStrength <= 0) continue;

        // Sample source pixel at (x, y) in source local space.
        const srcX = sourceLocal.x + (x - destLocalX);
        const srcY = sourceLocal.y + (y - destLocalY);
        const srcLocalX = srcX - srcBounds.left;
        const srcLocalY = srcY - srcBounds.top;
