        const srcClampedY = clampIndex(Math.round(srcLocalY), srcRegion.height);
        const srcOffset = (srcClampedY * srcRegion.width + srcClampedX) * 4;
        const srcR = srcRegion[srcOffset] ?? 0;
        const srcG = srcRegion[srcOffset + 1] ?? 0;
        const srcB = srcRegion[srcOffset + 2] ?? 0;
        const srcA = srcRegion[srcOffset + 3] ?? 0;

        // Composite onto destination working buffer.
        const dstOffset = ((y - minY) * patchWidth + (x - minX)) * 4;
        const dstR = patchPixels[dstOffset] ?? 0;
        const dstG = patchPixels[dstOffset + 1] ?? 0;
        const dstB = patchPixels[dstOffset + 2] ?? 0;
        const dstA = patchPixels[dstOffset + 3] ?? 0;

        const srcAlpha = (srcA / 255) * effectiveStrength;
        const dstAlpha = dstA / 255;
        const outAlpha = srcAlpha + dstAlpha * (1 - srcAlpha);
        if (outAlpha === 0) continue;
        patchPixels[dstOffset] = Math.round((srcR * srcAlpha + dstR * dstAlpha * (1 - srcAlpha)) / outAlpha);
