        patchPixels[dstOffset + 2] = Math.round((srcB * srcAlpha + dstB * dstAlpha * (1 - srcAlpha)) / outAlpha);
        patchPixels[dstOffset + 3] = Math.round(outAlpha * 255);
      }
    }
  }

  return { x: minX, y: minY, width: patchWidth, height: patchHeight, pixels: patchPixels };
}

