  BrushPoint,
  CloneState,
  CloneSource,
  CloneSourceRegion,
} from '../types.js';
import { TiledPixelStore } from '@freetoshop/pixel-storage';
import {
  clampIndex,
  compositeSourceOver,
  dabCoverage,
  documentDabBounds,
  emptyPatch,
