    const destLeft = Math.max(destinationRegionLeft, Math.floor(destinationLocal.localX - radius));
    const destTop = Math.max(destinationRegionTop, Math.floor(destinationLocal.localY - radius));
    const destRight = Math.min(destinationLocalSize.width - 1, Math.ceil(destinationLocal.localX + radius));
    const destBottom = Math.min(destinationLocalSize.height - 1, Math.ceil(destinationLocal.localY + radius));

