import type { ClonePatch, CloneSource, CloneSourceRegion } from './index.js';
import { TiledPixelStore } from '@freetoshop/pixel-storage';
import {
  BrushPoint,
  coverageStoreSample,
  clampIndex,
  documentDabBounds,
  maskCoverage,
  paintMaskStroke as rasterPaintMaskStroke,
  paintStroke as rasterPaintStroke,
  readSelectionRegion,
  selectionCoverage,
  type MaskBrushOptions,
} from './index.js';

export interface CloneStampBrushOptions {
  readonly size: number;
  readonly hardness: number;
  readonly opacity: number;
  readonly aligned: boolean;
}

/**
 * Source-destination offset established at the Alt/Option-click moment.
 * In aligned mode this offset is preserved throughout the gesture.
 */
export interface CloneOffset {
  readonly sourceX: number;
  readonly sourceY: number;
}

/**
 * Computes the source sample coordinate for a destination point.
 *
 * - Aligned mode: `source = destination - offset` where offset is fixed
 *   from the establish-click.
 * - Unaligned mode: `source = origin` (constant source origin).
 */
export function cloneSamplePoint(
  destination: number,
  sourceOrigin: number,
  offset: number,
  aligned: boolean,
): number {
  return aligned ? destination - offset : sourceOrigin;
}

/**
 * Reads source pixels from a TiledPixelStore for a destination dab's source coordinate.
 * Returns the pixels in a small local buffer (never the whole layer).
 */
export function readCloneSourceRegion(
  sourceStore: TiledPixelStore,
  sourceX: number,
  sourceY: number,
  radius: number,
): CloneSourceRegion {
  const bounds = documentDabBounds(sourceX, sourceY, radius, sourceStore.width, sourceStore.height);
  const region = sourceStore.read({
    x: bounds.left,
    y: bounds.top,
    width: bounds.right - bounds.left + 1,
    height: bounds.bottom - bounds.top + 1,
  });
  // Return a cloneable region descriptor (not a live reference).
  return {
    x: bounds.left,
    y: bounds.top,
    width: bounds.right - bounds.left + 1,
    height: bounds.bottom - bounds.top + 1,
    pixels: new Uint8ClampedArray(region),
  };
}

/**
 * Cloned source pixel sampling for a single destination pixel.
 * The source coordinate is in the *source* layer's local space (already transformed).
 */
export function cloneSamplePixel(
  sourceRegion: CloneSourceRegion,
  localSourceX: number,
  localSourceY: number,
  destinationOffset: number,
  destinationPixels: Uint8ClampedArray,
  opacity: number,
): void {
  const sx = clampIndex(localSourceX, sourceRegion.width);
  const sy = clampIndex(localSourceY, sourceRegion.height);
  const sourceOffset = (sy * sourceRegion.width + sx) * 4;
  const srcR = sourceRegion.pixels[sourceOffset] ?? 0;
  const srcG = sourceRegion.pixels[sourceOffset + 1] ?? 0;
  const srcB = sourceRegion.pixels[sourceOffset + 2] ?? 0;
  const srcA = sourceRegion.pixels[sourceOffset + 3] ?? 0;

  // Composite source-over with the source pixel's own alpha.
  const srcAlpha = (srcA / 255) * opacity;
  const dstAlpha = (destinationPixels[destinationOffset + 3] ?? 0) / 255;
  const outAlpha = srcAlpha + dstAlpha * (1 - srcAlpha);
  if (outAlpha === 0) return;
  destinationPixels[destinationOffset] = Math.round((srcR * srcAlpha + (destinationPixels[destinationOffset] ?? 0) * dstAlpha * (1 - srcAlpha)) / outAlpha);
  destinationPixels[destinationOffset + 1] = Math.round((srcG * srcAlpha + (destinationPixels[destinationOffset + 1] ?? 0) * dstAlpha * (1 - srcAlpha)) / outAlpha);
  destinationPixels[destinationOffset + 2] = Math.round((srcB * srcAlpha + (destinationPixels[destinationOffset + 2] ?? 0) * dstAlpha * (1 - srcAlpha)) / outAlpha);
  destinationPixels[destinationOffset + 3] = Math.round(outAlpha * 255);
}

export interface CloneStampStrokeOptions {
  readonly sourceStore: TiledPixelStore;
  readonly sourceLayerWorldTransform: {
    a: number;
    b: number;
    c: number;
    d: number;
    e: number;
    f: number;
