import type {
  BrushPoint,
  CloneState,
  CloneSource,
  CloneSourceRegion,
} from '../types.js';
import { TiledPixelStore } from '@freetoshop/pixel-storage';
import {
  clampIndex,
  compositeSourceOver,
  dabCoverage,
  documentDabBounds,
  emptyPatch,
  include,
  makePatchFromRegion,
  readSelectionRegion,
  selectionCoverage,
  transformPoint,
  unionBounds,
} from './index.js';
import type { LayerTransform } from '@freetoshop/core-document';

/**
 * Clone Stamp tool.
 *
 * Source establishment: Alt/Option-click records a source document point on a source layer.
 * Aligned mode preserves source-to-destination offset across a gesture.
 * Unaligned mode restarts sampling from the source origin on every dab.
 *
 * Coordinate flow for each destination dab:
 *   destination document point
 *     -> source document point (offset or origin)
 *     -> source layer local point (via source world inverse)
 *     -> sample source pixelStore at that local point
 *     -> composite onto destination working buffer (source-over with source alpha)
 *
 * Selection and mask behavior: identical to the existing brush — destination-space
 * selection coverage gates writes, and the destination write uses the same patch model.
 */

export interface CloneStampOptions {
  readonly size: number;
  readonly hardness: number;
  readonly opacity: number;
  readonly aligned: boolean;
}

export interface CloneStampStrokeInput {
  readonly points: readonly BrushPoint[];
  readonly sourceDocumentId: string;
  readonly sourceLayerId: string;
  readonly sourceLayerLocalSize: { width: number; height: number };
  /**
   * Source layer world transform (layer.transform composed with any parent groups up to the document root).
   * Used to map a source document point into source layer local space.
   */
  readonly sourceWorldTransform: LayerTransform;
  /**
   * Inverse of sourceWorldTransform. Precomputed to avoid repeated inversion per dab.
   */
  readonly sourceWorldInverse: LayerTransform;
  /**
   * Document-space point where the source was established (Alt/Option-click position).
   * In aligned mode, source = destination + (sourceOrigin - destinationAtEstablish).
   */
  readonly sourceOrigin: BrushPoint;
  /**
   * Document-space point where the source was established.
   * Only the destination point at establish time matters for the offset.
   * Stored so we can compute offset = sourceOrigin - establishDestination.
   */
  readonly establishDestination: BrushPoint;
  readonly destinationLocalSize: { width: number; height: number };
  readonly destinationWorldTransform: LayerTransform;
  readonly destinationWorldInverse: LayerTransform;
  readonly destinationStore: TiledPixelStore;
  readonly selection: import('@freetoshop/core-document').SelectionMask | null;
  readonly options: CloneStampOptions;
}

const MAX_SOURCE_READ_RADIUS_PADDING = 2;

/**
 * Read a bounded source region covering the union of all source-point dabs.
 * Returns a CloneSourceRegion that is tile-bounded by construction.
 */
function readSourceRegion(
  store: TiledPixelStore,
  sourcePoints: readonly { localX: number; localY: number }[],
  radius: number,
): CloneSourceRegion {
  let bounds: { left: number; top: number; right: number; bottom: number } | null = null;
  for (const p of sourcePoints) {
    const b = documentDabBounds(p.localX, p.localY, radius, store.width, store.height);
    bounds = unionBounds(bounds, b);
  }
  if (bounds === null || bounds.right < bounds.left) {
    return { x: 0, y: 0, width: 0, height: 0, pixels: new Uint8ClampedArray() };
  }
  const region = store.read({
    x: bounds.left,
    y: bounds.top,
    width: bounds.right - bounds.left + 1,
    height: bounds.bottom - bounds.top + 1,
  });
  return {
    x: bounds.left,
    y: bounds.top,
    width: bounds.right - bounds.left + 1,
    height: bounds.bottom - bounds.top + 1,
    pixels: new Uint8ClampedArray(region),
  };
}

/**
 * One atomic undoable clone stamp stroke.
 *
 * Returns a destination PixelPatch. The caller is responsible for committing it via
 * patchPixels (or patchLayerRasterMask for mask target) and managing history.
 *
 * Because the destination store is read once for the working region and written once,
 * this operation is tile-bounded on both sides.
 */
export function cloneStampStroke(input: CloneStampStrokeInput): import('../types.js').ClonePatch {
  const {
    points,
    sourceWorldInverse,
    sourceOrigin,
    establishDestination,
    destinationLocalSize,
    destinationWorldInverse,
    destinationStore,
    selection,
    options,
  } = input;

  if (points.length === 0) {
    return emptyPatch();
  }
  if (options.size <= 0 || options.opacity <= 0) {
    return emptyPatch();
  }

  const radius = options.size / 2;
  const hardness = options.hardness;
  const opacity = options.opacity;

  // Step 1: build interpolated dabs (same spacing logic as brush).
  const dabs: Array<{ x: number; y: number; pressure: number }> = [];
  dabs.push({ x: points[0].x, y: points[0].y, pressure: points[0].pressure ?? 1 });
  const spacing = Math.max(0.25, radius * 0.5);
  for (let i = 1; i < points.length; i++) {
    const prev = points[i - 1];
    const curr = points[i];
    const dist = Math.hypot(curr.x - prev.x, curr.y - prev.y);
    const count = Math.max(1, Math.ceil(dist / spacing));
    for (let step = 1; step <= count; step++) {
      const t = step / count;
      dabs.push({
        x: prev.x + (curr.x - prev.x) * t,
        y: prev.y + (curr.y - prev.y) * t,
        pressure: (prev.pressure ?? 1) + ((curr.pressure ?? 1) - (prev.pressure ?? 1)) * t,
      });
    }
  }

  // Step 2: destination working region (union of local dab bounds in destination local space).
  const destinationDabLocalPoints: Array<{ localX: number; localY: number }> = [];
  let destinationBounds: { left: number; top: number; right: number; bottom: number } | null = null;
  for (const dab of dabs) {
    const local = transformPoint(destinationWorldInverse, dab.x, dab.y);
    destinationDabLocalPoints.push(local);
    const b = documentDabBounds(local.localX, local.localY, radius, destinationLocalSize.width, destinationLocalSize.height);
    destinationBounds = unionBounds(destinationBounds, b);
  }
  if (destinationBounds === null || destinationBounds.right < destinationBounds.left) {
    return emptyPatch();
  }
  const destinationRegionLeft = destinationBounds.left;
  const destinationRegionTop = destinationBounds.top;
  const destinationRegionWidth = destinationBounds.right - destinationBounds.left + 1;
  const destinationRegionHeight = destinationBounds.bottom - destinationBounds.top + 1;

  const destinationWorking = new Uint8ClampedArray(destinationRegionWidth * destinationRegionHeight * 4);
  const destinationRegion = destinationStore.read({
    x: destinationRegionLeft,
    y: destinationRegionTop,
    width: destinationRegionWidth,
    height: destinationRegionHeight,
  });
  destinationWorking.set(destinationRegion);

  const selectionRegion = readSelectionRegion(selection, dabs, radius);
  let changedBounds: { left: number; top: number; right: number; bottom: number } | null = null;

  // Step 3: for each dab, compute source point and sample source layer.
  for (let i = 0; i < dabs.length; i++) {
    const dab = dabs[i];
    const destinationLocal = destinationDabLocalPoints[i];

    // Source document point: offset-based (aligned) or origin-based (unaligned).
    const sourceDocumentPoint: { x: number; y: number } =
      options.aligned
        ? {
            x: dab.x + (sourceOrigin.x - establishDestination.x),
            y: dab.y + (sourceOrigin.y - establishDestination.y),
          }
        : { x: sourceOrigin.x, y: sourceOrigin.y };

    // Source layer local point.
    const sourceLocalPoint = transformPoint(sourceWorldInverse, sourceDocumentPoint.x, sourceDocumentPoint.y);

    // Source working region for this dab (we could precompute union across all dabs for efficiency,
    // but reading per-dab keeps the implementation simple and still tile-bounded).
    // For efficiency, we'll read the source region once per dab. The union of all dabs is bounded.
    const sourceBounds = documentDabBounds(
      sourceLocalPoint.localX,
      sourceLocalPoint.localY,
      radius,
      input.sourceLayerLocalSize.width,
      input.sourceLayerLocalSize.height,
    );
    if (sourceBounds.right < sourceBounds.left || sourceBounds.bottom < sourceBounds.top) {
      continue;
    }
    const sourceRegion = input.sourceStore.read({
      x: sourceBounds.left,
      y: sourceBounds.top,
      width: sourceBounds.right - sourceBounds.left + 1,
      height: sourceBounds.bottom - sourceBounds.top + 1,
    });

    // Paint destination dabs overlapping this source dab's footprint.
    const destLeft = Math.max(destinationRegionLeft, Math.floor(destinationLocal.localX - radius));
    const destTop = Math.max(destinationRegionTop, Math.floor(destinationLocal.localY - radius));
    const destRight = Math.min(destinationLocalSize.width - 1, Math.ceil(destinationLocal.localX + radius));
    const destBottom = Math.min(destinationLocalSize.height - 1, Math.ceil(destinationLocal.localY + radius));

    for (let y = destTop; y <= destBottom; y++) {
      for (let x = destLeft; x <= destRight; x++) {
        const docX = transformPoint(destinationWorldTransform, x, y).x;
        const docY = transformPoint(destinationWorldTransform, x, y).y;
        const dist = Math.hypot(docX - dab.x, docY - dab.y);
        const coverage = dabCoverage(dist, radius, hardness) * opacity * dab.pressure;
        if (coverage <= 0) continue;

        const selected = selectionCoverage(
          selection,
          docX,
          docY,
          selectionRegion.buffer,
          selectionRegion.region,
        );
        const effectiveCoverage = coverage * selected;
        if (effectiveCoverage <= 0) continue;

        // Sample source pixel at (x, y) in source-local space, but mapped through source local point.
        // The source pixel that maps to this destination pixel is at:
        //   sourceLocal = sourceLocalPoint + (destinationPixelLocal - destinationLocal)
        // This is because in aligned mode the offset is constant in document space,
        // and we've already mapped sourceDocumentPoint to sourceLocalPoint.
        const sourcePixelLocalX = sourceLocalPoint.localX + (x - destinationLocal.localX);
        const sourcePixelLocalY = sourceLocalPoint.localY + (y - destinationLocal.localY);

        const clampedSourceX = clampIndex(Math.round(sourcePixelLocalX), sourceRegion.width);
        const clampedSourceY = clampIndex(Math.round(sourcePixelLocalY), sourceRegion.height);
        const sourceOffset =
          (clampedSourceY * (sourceBounds.right - sourceBounds.left + 1) + clampedSourceX) * 4;

        const srcR = sourceRegion[sourceOffset] ?? 0;
        const srcG = sourceRegion[sourceOffset + 1] ?? 0;
        const srcB = sourceRegion[sourceOffset + 2] ?? 0;
        const srcA = sourceRegion[sourceOffset + 3] ?? 0;

        const destinationOffset = ((y - destinationRegionTop) * destinationRegionWidth + (x - destinationRegionLeft)) * 4;
        const before = [
          destinationWorking[destinationOffset],
          destinationWorking[destinationOffset + 1],
          destinationWorking[destinationOffset + 2],
          destinationWorking[destinationOffset + 3],
        ];

        compositeSourceOver(destinationWorking, destinationOffset, [srcR, srcG, srcB, srcA], effectiveCoverage);

        if (
          before[0] !== destinationWorking[destinationOffset] ||
          before[1] !== destinationWorking[destinationOffset + 1] ||
          before[2] !== destinationWorking[destinationOffset + 2] ||
          before[3] !== destinationWorking[destinationOffset + 3]
        ) {
          changedBounds = include(changedBounds, x, y);
        }
      }
    }
  }

  return makePatchFromRegion(
    destinationRegionLeft,
    destinationRegionTop,
    destinationRegionWidth,
    destinationWorking,
    changedBounds,
  );
}

/**
 * Clone Stamp tool types.
 *
 * These types deliberately capture the testable data model (source, offset, aligned/unaligned)
 * rather than leaving that state implicit in UI handlers.
 */

export interface BrushPoint {
  readonly x: number;
  readonly y: number;
  readonly pressure?: number;
}

/**
 * Explicit representation of a clone source.
 *
 * - documentId: identifier of the source document (must match the active document during a stroke).
 * - layerId: identifier of the source layer within that document.
 * - origin: document-space point where the source was established (Alt/Option-click).
 * - aligned: when true, the source-to-destination offset is preserved across the gesture.
 */
export interface CloneSource {
  readonly documentId: string;
  readonly layerId: string;
  readonly origin: BrushPoint;
  readonly aligned: boolean;
}

/**
 * The UI-visible source state.
 * hasSource indicates whether a source has been established.
 * source is the active source when hasSource is true.
 */
export interface CloneState {
  readonly hasSource: boolean;
  readonly source: CloneSource | null;
}

/**
 * A bounded read from the source pixel store.
 * This is the unit of tile-bounded work for clone sampling.
 */
export interface CloneSourceRegion {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
  readonly pixels: Uint8ClampedArray;
}

/**
 * Destination patch produced by a clone stamp stroke.
 * Reuses the existing PixelPatch shape so it plugs into patchPixels.
 */
export interface ClonePatch {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
  readonly pixels: Uint8ClampedArray;
}

/** Empty patch sentinel. */
export function emptyClonePatch(): ClonePatch {
  return { x: 0, y: 0, width: 0, height: 0, pixels: new Uint8ClampedArray() };
}

/** Empty source region sentinel. */
export function emptyCloneSourceRegion(): CloneSourceRegion {
  return { x: 0, y: 0, width: 0, height: 0, pixels: new Uint8ClampedArray() };
}

import type { BrushPoint } from '../index.js';
import { TiledPixelStore } from '@freetoshop/pixel-storage';
import type { LayerTransform } from '@freetoshop/core-document';

/**
 * Clone Stamp source state.
 *
 * This is the explicit, testable data model for the clone source.
 * It is separate from the brush/eraser tools and from UI handlers.
 */
export interface CloneSource {
  /** Identifier of the source document. Must match the active document during a stroke. */
  readonly documentId: string;
  /** Layer from which pixels are sampled. */
  readonly layerId: string;
  /** Document-space point where the source was established (Alt/Option-click). */
  readonly originX: number;
  readonly originY: number;
  /** When true, the source-to-destination offset is preserved across the gesture. */
  readonly aligned: boolean;
}

/**
 * Explicit representation of whether a valid source exists and, when present, its parameters.
 * This is the UI-visible state for the Clone Stamp tool.
 */
export interface CloneState {
  readonly hasSource: boolean;
  readonly source: CloneSource | null;
}

/**
 * Rectangle of source pixels that must be read for a tile write to remain tile-bounded.
 */
export interface CloneSourceRegion {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
  readonly pixels: Uint8ClampedArray;
}

/**
 * Destination patch produced by a clone stamp stroke.
 * Reuses the existing PixelPatch shape so it plugs into the existing patchPixels command.
 */
export interface ClonePatch {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
  readonly pixels: Uint8ClampedArray;
}

/** Sentinel for an empty patch. */
export function emptyClonePatch(): ClonePatch {
  return { x: 0, y: 0, width: 0, height: 0, pixels: new Uint8ClampedArray() };
}

/** Sentinel for an empty source region. */
export function emptyCloneSourceRegion(): CloneSourceRegion {
  return { x: 0, y: 0, width: 0, height: 0, pixels: new Uint8ClampedArray() };
}

/** Brush-point shape reused by clone strokes (document-space position plus optional pressure). */
export type CloneBrushPoint = BrushPoint;

/**
 * Clone stroke brush options.
 * Reuses size/hardness/opacity semantics from the existing brush tooling.
 */
export interface CloneBrushOptions {
  readonly size: number;
  readonly hardness: number;
  readonly opacity: number;
}

/**
 * Parameters needed to establish a clone source from a source document and layer.
 */
export interface EstablishCloneSourceParams {
  readonly sourceDocumentId: string;
  readonly sourceLayerId: string;
  readonly sourcePointX: number;
  readonly sourcePointY: number;
  readonly aligned: boolean;
}

/**
 * The source-to-destination offset established at the Alt/Option-click moment.
 * In aligned mode this offset is preserved for the entire gesture.
 */
export interface CloneOffset {
  readonly sourceX: number;
  readonly sourceY: number;
}

/**
 * Compute the source offset established at the Alt/Option-click.
 * Both points are in document space of the same document.
 */
export function computeCloneOffset(
  sourcePoint: { x: number; y: number },
  destinationPoint: { x: number; y: number },
): CloneOffset {
  return {
    sourceX: sourcePoint.x - destinationPoint.x,
    sourceY: sourcePoint.y - destinationPoint.y,
  };
}

/**
 * Determine the source document-space point to sample for a destination point.
 *
 * - Aligned: `source = destination + offset`, preserving the established offset.
 * - Unaligned: `source = sourceOrigin`, restarting from the source origin each dab.
 */
export function sampleSourcePoint(
  destinationX: number,
  destinationY: number,
  sourceOriginX: number,
  sourceOriginY: number,
  offset: CloneOffset | null,
  aligned: boolean,
): { sourceX: number; sourceY: number } {
  if (aligned && offset !== null) {
    return {
      sourceX: destinationX + offset.sourceX,
      sourceY: destinationY + offset.sourceY,
    };
  }
  return { sourceX: sourceOriginX, sourceY: sourceOriginY };
}

/**
 * Map a source document-space point into source-layer local space using the source world transform inverse.
 */
export function sourceDocumentToLocal(
  transform: LayerTransform,
  inverse: LayerTransform,
  sourceX: number,
  sourceY: number,
): { localX: number; localY: number } {
  // A point in document space of the source document is transformed by the inverse of the source world transform
  // to get the layer-local coordinate.
  // Note: sourceWorldTransform maps local -> document, so inverse maps document -> local.
  const localX = inverse.a * sourceX + inverse.c * sourceY + inverse.e;
  const localY = inverse.b * sourceX + inverse.d * sourceY + inverse.f;
  return { localX, localY };
}

/**
 * Read a bounded region from the source pixel store.
 * The region is the union of dab footprints in source-local space.
 * This stays tile-bounded because it uses TiledPixelStore.read.
 */
export function readSourceRegion(
  store: TiledPixelStore,
  dabs: readonly { localX: number; localY: number }[],
  radius: number,
  sourceLayerSize: { width: number; height: number },
): CloneSourceRegion {
  if (dabs.length === 0) return emptyCloneSourceRegion();

  let bounds: { left: number; top: number; right: number; bottom: number } | null = null;
  for (const dab of dabs) {
    const b = documentDabBoundsLocal(dab.localX, dab.localY, radius, sourceLayerSize.width, sourceLayerSize.height);
    bounds = unionBoundsLocal(bounds, b);
  }
  if (bounds === null || bounds.right < bounds.left) return emptyCloneSourceRegion();

  const region = store.read({
    x: bounds.left,
    y: bounds.top,
    width: bounds.right - bounds.left + 1,
    height: bounds.bottom - bounds.top + 1,
  });
  return {
    x: bounds.left,
    y: bounds.top,
    width: bounds.right - bounds.left + 1,
    height: bounds.bottom - bounds.top + 1,
    pixels: new Uint8ClampedArray(region),
  };
}

/**
 * Local-space dab bounds (mirrors documentDabBounds but for local coordinates).
 */
function documentDabBoundsLocal(
  x: number,
  y: number,
  radius: number,
  width: number,
  height: number,
): { left: number; top: number; right: number; bottom: number } {
  return {
    left: Math.max(0, Math.floor(x - radius)),
    top: Math.max(0, Math.floor(y - radius)),
    right: Math.min(width - 1, Math.ceil(x + radius)),
    bottom: Math.min(height - 1, Math.ceil(y + radius)),
  };
}

function unionBoundsLocal(
  left: { left: number; top: number; right: number; bottom: number } | null,
  right: { left: number; top: number; right: number; bottom: number },
): { left: number; top: number; right: number; bottom: number } | null {
  if (left === null) return { ...right };
  return {
    left: Math.min(left.left, right.left),
    top: Math.min(left.top, right.top),
    right: Math.max(left.right, right.right),
    bottom: Math.max(left.bottom, right.bottom),
  };
}

